statements.statement:
SELECT DISTINCT hex(TPoll.PollK) AS PollK, TPoll.FHeader, TPoll.FName, TPoll.FDescription, DATE(TPoll.CreateD) AS CreateD,
   (SELECT COUNT(DISTINCT TPollVote.FTie) FROM TPollVote JOIN TPollAnswer ON TPollAnswer.PollAnswerK = TPollVote.PollAnswerK 
   JOIN TPollQuestion ON TPollQuestion.PollQuestionK = TPollAnswer.PollQuestionK 
   WHERE TPollQuestion.PollK = TPoll.PollK) AS TotalVotes 
FROM TPoll LEFT JOIN rRecordxTag ON (rRecordxTag.FKey = TPoll.PollK AND rRecordxTag.table_number = 1060) 
{++where} 
{++orderby} 
{++limit}
